                            key={tag.id} 
                            variant={isSelected ? "default" : "outline"}
                            className="cursor-pointer hover:bg-blue-100 dark:hover:bg-blue-900 text-xs"
                            onClick={() => {
                              if (!isSelected) {
                                const updatedTags = formData.tags 
                                  ? `${formData.tags}, ${tag.name}`
                                  : tag.name;
                                setFormData({ ...formData, tags: updatedTags });
                              }
                            }}
                          >
