        return res.status(403).json({ message: "Access denied" });
      }

      const { id } = req.params;
      const validatedData = updateBlogTagSchema.parse(req.body);
      const tag = await storage.updateBlogTag(id, validatedData);
      res.json(tag);
    } catch (error: any) {
      console.error("Error updating blog tag:", error);
      if (error.name === 'ZodError') {
        return res.status(400).json({ message: "Validation error", errors: error.errors });
      }
      res.status(500).json({ message: "Failed to update blog tag" });
    }
  });

  app.delete("/api/admin/blog/tags/:id", isAuthenticated, requireOnboarding, async (req: any, res: Response) => {
    try {
      if (req.user.role !== 'admin') {
        return res.status(403).json({ message: "Access denied" });
      }

      const { id } = req.params;
      await storage.deleteBlogTag(id);
      res.json({ message: "Blog tag deleted successfully" });
    } catch (error: any) {
      console.error("Error deleting blog tag:", error);
      res.status(500).json({ message: "Failed to delete blog tag" });
    }
  });

  const httpServer = createServer(app);
  return httpServer;
}

